47	import org.springframework.samples.petclinic.rest.dto.VisitDto;
48	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
49	import org.springframework.samples.petclinic.service.ClinicService;
50	import org.springframework.samples.petclinic.util.HashUtils;
51	import org.springframework.security.access.prepost.PreAuthorize;
52	import org.springframework.web.bind.annotation.CrossOrigin;
53	import org.springframework.web.bind.annotation.RequestMapping;
54	import org.springframework.web.bind.annotation.RestController;
55	import org.springframework.web.context.request.RequestContextHolder;
56	import org.springframework.web.context.request.ServletRequestAttributes;
57	import org.springframework.web.util.UriComponentsBuilder;
58	
59	import tools.jackson.databind.ObjectMapper;
60	import tools.jackson.databind.json.JsonMapper;
61	
62	import jakarta.transaction.Transactional;
63	
64	/**
65	 * @author Vitaliy Fedoriv
66	 */
67	
68	@RestController
69	@CrossOrigin(exposedHeaders = "errors, content-type")
70	@RequestMapping("/api")
71	public class OwnerRestControllerV1 implements OwnersApi {
72	
73	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
74	
75	    /**
76	     * Dedicated logger for the welcome notification enqueued when an owner is successfully created.
77	     * The emitted line carries the owner's id and its unified {@link Owner#getMemberId() memberId} so
78	     * downstream notification consumers can address the welcome to the newly registered owner.
79	     */
80	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
81	
82	    /**
83	     * Serializes {@link OwnerCreatedEvent structured audit events} to their JSON form. Stateless and
84	     * thread-safe, so a single shared instance serves every create.
85	     */
86	    private static final ObjectMapper AUDIT_MAPPER = JsonMapper.builder().build();
87	
88	    /**
89	     * Monotonically increasing sequence stamped onto each {@link OwnerCreatedEvent OWNER_CREATED}
90	     * event, so the ordering of creates is recoverable from the audit stream alone. Shared across all
91	     * creates (hence {@code static}) and incremented once per emitted event.
92	     */
93	    private static final AtomicLong AUDIT_SEQ = new AtomicLong();
94	
95	    /**
96	     * Immutable structured audit event emitted (as JSON) alongside the human-readable audit line when
97	     * an owner is created. Its {@code memberId} component carries the owner's <em>primary
98	     * identifier</em>, the unified {@link Owner#getMemberId() memberId}, so downstream consumers always
99	     * read the owner's primary identifier from the same event.
100	     *
101	     * <p>The component order matches the serialized field order
102	     * {@code {seq, ownerId, memberId, membershipLevel, event}}.
103	     */
104	    private record OwnerCreatedEvent(long seq, Integer ownerId, String memberId,
105	                                     Integer membershipLevel, String event) {
106	
107	        private static final String OWNER_CREATED = "OWNER_CREATED";
108	
109	        static OwnerCreatedEvent of(long seq, Owner owner) {
110	            return new OwnerCreatedEvent(seq, owner.getId(), primaryIdentifier(owner),
111	                owner.getMembershipLevel(), OWNER_CREATED);
112	        }
113	
114	        /**
115	         * The owner's primary identifier: its unified {@link Owner#getMemberId() memberId}.
116	         */
117	        private static String primaryIdentifier(Owner owner) {
118	            return owner.getMemberId();
119	        }
120	    }
121	
122	    /**
123	     * The HTTP request header a client may send to make a create idempotent. When a create repeats
124	     * with a key already seen, the originally created owner is returned instead of a duplicate.
125	     */
126	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
127	
128	    /**
129	     * Remembers, per {@link #IDEMPOTENCY_KEY_HEADER Idempotency-Key}, the id of the owner that key's
130	     * first successful create produced, so a repeat of that create can return the same owner rather
131	     * than creating a duplicate.
132	     */
133	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
134	
135	    /**
136	     * Fixed public-holiday calendar. A registration date that lands on one of these dates is rolled
137	     * forward to the next non-holiday business day, in the same way weekends are.
138	     */
139	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
140	        LocalDate.of(2026, 1, 1),
141	        LocalDate.of(2026, 1, 26),
142	        LocalDate.of(2026, 4, 25),
143	        LocalDate.of(2026, 12, 25),
144	        LocalDate.of(2026, 12, 28));
145	
146	    private final ClinicService clinicService;
147	
148	    private final OwnerMapper ownerMapper;
149	
150	    private final PetMapper petMapper;
151	
152	    private final VisitMapper visitMapper;
153	
154	    private final AddressNormalizer addressNormalizer;
155	
156	    public OwnerRestControllerV1(ClinicService clinicService,
157	                                 OwnerMapper ownerMapper,
158	                                 PetMapper petMapper,
159	                                 VisitMapper visitMapper,
160	                                 AddressNormalizer addressNormalizer) {
161	        this.clinicService = clinicService;
162	        this.ownerMapper = ownerMapper;
163	        this.petMapper = petMapper;
164	        this.visitMapper = visitMapper;
165	        this.addressNormalizer = addressNormalizer;
166	    }
167	
168	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
169	    @Override
170	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
171	        Collection<Owner> owners;
172	        if (lastName != null) {
173	            owners = this.clinicService.findOwnerByLastName(lastName);
174	        } else {
175	            owners = this.clinicService.findAllOwners();
176	        }
177	        if (owners.isEmpty()) {
178	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
179	        }
180	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
181	    }
182	
183	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
184	    @Override
185	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
186	        Owner owner = this.clinicService.findOwnerById(ownerId);
187	        if (owner == null) {
188	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
189	        }
190	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
191	    }
192	
193	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
194	    @Override
195	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
196	        String idempotencyKey = currentIdempotencyKey();
197	        if (idempotencyKey != null) {
198	            Integer existingId = idempotentCreates.get(idempotencyKey);
199	            if (existingId != null) {
200	                Owner existing = this.clinicService.findOwnerById(existingId);
201	                if (existing != null) {
202	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
203	                }
204	            }
205	        }
206	
207	        ResponseEntity<OwnerDto> response = createOwner(ownerFieldsDto);
208	
209	        if (idempotencyKey != null && response.getStatusCode() == HttpStatus.CREATED
210	            && response.getBody() != null && response.getBody().getId() != null) {
211	            idempotentCreates.put(idempotencyKey, response.getBody().getId());
212	        }
213	        return response;
214	    }
215	
216	    /**
217	     * The non-blank {@link #IDEMPOTENCY_KEY_HEADER Idempotency-Key} header of the request currently
218	     * being handled, or {@code null} when the request carries no such header (or no request is bound
219	     * to the current thread). Used to make a repeated create return the originally created owner.
220	     */
221	    private String currentIdempotencyKey() {
222	        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes)) {
223	            return null;
224	        }
225	        String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
226	        return (key == null || key.isBlank()) ? null : key;
227	    }
228	
229	    /**
230	     * Run the full owner-creation pipeline for a submitted {@link OwnerFieldsDto} and build its
231	     * response. The submitted fields are mapped to an {@link Owner}, which is
232	     * {@link #normalizeAndValidate(Owner) normalized and validated}, checked against the
233	     * {@link #isDailyLimitReached(LocalDate) daily creation limit}, {@link #assignHousehold(Owner)
234	     * assigned its household} and screened for {@link #checkForConflicts(Owner) conflicts};
235	     * a surviving owner then has its {@link #assignDerivedAttributes(Owner, boolean) derived
236	     * attributes} assigned, is persisted and audited. Returns the {@link #created(Owner) 201 Created}
237	     * response for the persisted owner, or the {@link HttpStatus} the create must fail with
238	     * ({@code 400 Bad Request}, {@code 429 Too Many Requests} or {@code 409 Conflict}) when the owner
239	     * cannot be created.
240	     */
241	    private ResponseEntity<OwnerDto> createOwner(OwnerFieldsDto ownerFieldsDto) {
242	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
243	
244	        HttpStatus invalid = normalizeAndValidate(owner);
245	        if (invalid != null) {
246	            return new ResponseEntity<>(invalid);
247	        }
248	        if (isDailyLimitReached(owner.getRegistrationDate())) {
249	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
250	        }
251	
252	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
253	        assignHousehold(owner);
254	
255	        HttpStatus conflict = checkForConflicts(owner);
256	        if (conflict != null) {
257	            return new ResponseEntity<>(conflict);
258	        }
259	
260	        assignDerivedAttributes(owner, sharesHousehold);
261	        this.clinicService.saveOwner(owner);
262	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
263	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
264	            owner.getMembershipLevel());
265	        emitOwnerCreatedEvent(owner);
266	        enqueueWelcomeNotification(owner);
267	        return created(owner);
268	    }
