290	    /**
291	     * Bring a freshly mapped owner into its canonical, valid form, or report the reason it must be
292	     * rejected. The owner's {@link #normalizeAddress(Owner) address is normalized} (a missing address
293	     * is rejected), its telephone is converted to E.164 (an unconvertible number is rejected), its
294	     * postcode is checked against its city's region, a registration date in the future is rejected,
295	     * and the effective registration date (the supplied one, or today when none was given) is rolled
296	     * onto a business day and stored back on the owner. Returns {@code null} once the owner is valid
297	     * and normalized, or the {@link HttpStatus} the create must fail with ({@code 400 Bad Request})
298	     * otherwise.
299	     */
300	    private HttpStatus normalizeAndValidate(Owner owner) {
301	        if (!normalizeAddress(owner)) {
302	            return HttpStatus.BAD_REQUEST;
303	        }
304	        String telephone = toE164(owner.getTelephone());
305	        if (telephone == null) {
306	            return HttpStatus.BAD_REQUEST;
307	        }
308	        owner.setTelephone(telephone);
309	        if (isDisposableEmail(owner.getEmail())) {
310	            return HttpStatus.BAD_REQUEST;
311	        }
312	        if (!owner.isPostcodeValid()) {
313	            return HttpStatus.BAD_REQUEST;
314	        }
315	        if (owner.getRegistrationDate() != null
316	            && owner.getRegistrationDate().isAfter(LocalDate.now())) {
317	            return HttpStatus.BAD_REQUEST;
318	        }
319	        LocalDate effectiveDate = owner.getRegistrationDate() != null
320	            ? owner.getRegistrationDate() : LocalDate.now();
321	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
322	        return null;
323	    }
