359	    /**
360	     * The set of disposable (throwaway) email domains that an owner's email may not use. An owner
361	     * whose email is hosted on one of these domains is rejected with {@code 400 Bad Request}.
362	     */
363	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
364	        "mailinator.com", "tempmail.com", "guerrillamail.com");
365	
366	    /**
367	     * Whether the given email is hosted on a {@linkplain #DISPOSABLE_EMAIL_DOMAINS disposable}
368	     * domain. The email is optional, so a {@code null} or empty email is not disposable; otherwise
369	     * its {@linkplain Owner#emailDomainOf(String) domain} (compared case-insensitively) is matched
370	     * against the blocklist.
371	     */
372	    private boolean isDisposableEmail(String email) {
373	        String domain = Owner.emailDomainOf(email);
374	        return domain != null && DISPOSABLE_EMAIL_DOMAINS.contains(domain);
375	    }
