390	    /**
391	     * Whether the owner clashes with an owner that already exists, and the {@link HttpStatus} the
392	     * create must fail with when it does. An owner is rejected with {@code 409 Conflict} when it
393	     * {@linkplain #isDuplicateIdentity(Owner) duplicates an existing owner's identity key} or when
394	     * its {@link #isCityAtCapacity(String) city is already at capacity}. Sharing a household (the
395	     * same surname sound and postcode) but with a different identity key is not a conflict: such an
396	     * owner is admitted and later {@linkplain #findSoftDuplicate(Owner) flagged as a possible
397	     * duplicate}. Returns {@code null} when the owner clashes with nothing and may be created.
398	     */
399	    private HttpStatus checkForConflicts(Owner owner) {
400	        if (isDuplicateIdentity(owner)) {
401	            return HttpStatus.CONFLICT;
402	        }
403	        if (isCityAtCapacity(owner.getCity())) {
404	            return HttpStatus.CONFLICT;
405	        }
406	        return null;
407	    }
