409	    /**
410	     * Whether an existing owner already carries this owner's {@link Owner#getIdentityKey() identity
411	     * key}. This is the single hard-duplicate rule: two owners are duplicates exactly when their
412	     * identity keys are equal, and the second is rejected with {@code 409 Conflict}. Like the other
413	     * identity rules it considers only the {@linkplain #activeOwners() active owners}, so an owner
414	     * flagged {@linkplain Owner#isDeleted() deleted} never triggers a duplicate. The email-domain
415	     * blocklist is applied earlier, during {@link #normalizeAndValidate(Owner) validation}, so a
416	     * disposable-email owner is rejected before it reaches this check.
417	     */
418	    private boolean isDuplicateIdentity(Owner owner) {
419	        String identityKey = owner.getIdentityKey();
420	        return activeOwners().stream()
421	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
422	    }
