435	    /**
436	     * Assign the attributes that are derived once, at creation time, and stored on the owner: its
437	     * {@link #memberId(Owner) memberId}, {@link #namesakeCount(String, String) namesakeCount},
438	     * {@link #isBulkSignup(LocalDate) bulk-signup warning}, {@link #isCityApproachingCapacity(String)
439	     * capacity warning}, {@link #householdSize(String)
440	     * householdSize} and {@link #membershipLevel(Owner) membershipLevel}. Each is computed from the
441	     * owner's own fields together with the owners already present, so this runs after the owner has
442	     * been validated and has passed the duplicate and capacity checks, and immediately before it is
443	     * persisted.
444	     */
445	    private void assignDerivedAttributes(Owner owner, boolean sharesHousehold) {
446	        owner.setMemberId(memberId(owner));
447	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
448	        owner.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
449	        owner.setCapacityWarning(isCityApproachingCapacity(owner.getCity()));
450	        owner.setHouseholdSize(householdSize(owner.getHouseholdId()));
451	        owner.setMembershipLevel(membershipLevel(owner));
452	        assignPossibleDuplicate(owner, sharesHousehold);
453	        owner.setRiskFlag(isRiskFlagged(owner));
454	    }
