456	    /**
457	     * Whether a newly created owner should be flagged for review. True when any of these hold: the
458	     * owner is a {@linkplain Owner#getPossibleDuplicate() possible duplicate}, its email domain is
459	     * {@linkplain #isDisposableAdjacentEmail(String) disposable-adjacent}, or its city is over its
460	     * soft capacity (the city is {@linkplain #isCityApproachingCapacity(String) approaching capacity},
461	     * so its {@link Owner#getCapacityWarning() capacityWarning} is set); otherwise false. Computed
462	     * during {@link #assignDerivedAttributes(Owner, boolean)}, after the possible-duplicate and
463	     * capacity-warning attributes it reads have already been assigned.
464	     */
465	    private boolean isRiskFlagged(Owner owner) {
466	        return Boolean.TRUE.equals(owner.getPossibleDuplicate())
467	            || isDisposableAdjacentEmail(owner.getEmail())
468	            || Boolean.TRUE.equals(owner.getCapacityWarning());
469	    }
