471	    /**
472	     * Whether the given email's domain is disposable-adjacent: a subdomain of a known
473	     * {@linkplain #DISPOSABLE_EMAIL_DOMAINS disposable} domain (e.g. {@code x.mailinator.com}). An
474	     * exactly-disposable domain is rejected earlier during {@link #normalizeAndValidate(Owner)
475	     * validation}, so it never reaches here; a subdomain is admitted but still flagged as adjacent.
476	     * The email is optional, so a {@code null} or empty email is not disposable-adjacent; otherwise
477	     * its {@linkplain Owner#emailDomainOf(String) domain} (compared case-insensitively) is tested.
478	     */
479	    private boolean isDisposableAdjacentEmail(String email) {
480	        String domain = Owner.emailDomainOf(email);
481	        if (domain == null) {
482	            return false;
483	        }
484	        return DISPOSABLE_EMAIL_DOMAINS.stream()
485	            .anyMatch(disposable -> domain.endsWith("." + disposable));
486	    }
