488	    /**
489	     * The membership level to assign a newly created owner and store on it as its
490	     * {@link Owner#getMembershipLevel() membershipLevel}: the owner's own
491	     * {@linkplain Owner#getBaseMembershipLevel() base level} derived from its membershipPoints,
492	     * capped so it cannot exceed one above the current maximum membershipLevel among the owner's
493	     * existing {@linkplain #householdMembers(String) household members}. With no existing household
494	     * member no cap applies and the base level is used as-is. This is the single place the stored
495	     * membership level is derived; it runs during {@link #assignDerivedAttributes(Owner, boolean)},
496	     * after the owner has passed the duplicate and capacity checks and so has its household members
497	     * available to it.
498	     */
499	    private Integer membershipLevel(Owner owner) {
500	        int base = owner.getBaseMembershipLevel();
501	        Collection<Owner> members = householdMembers(owner.getHouseholdId());
502	        if (members.isEmpty()) {
503	            return base;
504	        }
505	        int householdMax = members.stream()
506	            .mapToInt(Owner::getMembershipLevel)
507	            .max()
508	            .getAsInt();
509	        return Math.min(base, householdMax + 1);
510	    }
