512	    /**
513	     * Flag a newly created owner as a possible (soft) duplicate. An owner that declares it shares a
514	     * household ({@code sharesHousehold}) is a declared household member, not a suspected duplicate,
515	     * so it is never flagged. Otherwise it is flagged only when it is a soft match of an existing
516	     * owner as determined by {@link #findSoftDuplicate(Owner)}. When such an owner exists the new owner is flagged with
517	     * {@code possibleDuplicate = true} and {@code possibleDuplicateOf} set to that owner's id;
518	     * otherwise {@code possibleDuplicate = false} and no matching id is recorded.
519	     */
520	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
521	        Owner match = sharesHousehold ? null : findSoftDuplicate(owner);
522	        owner.setPossibleDuplicate(match != null);
523	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
524	    }
525	
526	    /**
527	     * The owners a newly created owner is checked against by the duplicate and identity rules:
528	     * the {@link #householdMembers(String) household} membership and {@link #findSoftDuplicate(Owner)
529	     * soft-duplicate} checks, the {@link #memberId(Owner) memberId} de-duplication and the
530	     * {@link #namesakeCount(String, String) namesake} count. This is the single place that scope is
531	     * defined, so every one of those rules considers exactly the same set of owners; it spans every
532	     * owner the clinic holds except those flagged {@linkplain Owner#isDeleted() deleted}, which a
533	     * soft delete retains but excludes from duplicate and identity detection.
534	     */
535	    private Collection<Owner> activeOwners() {
536	        return this.clinicService.findAllOwners().stream()
537	            .filter(owner -> !owner.isDeleted())
538	            .collect(Collectors.toList());
539	    }
540	
541	    /**
542	     * The existing owner this owner softly duplicates, or {@code null} when there is none. A soft
543	     * match is an existing owner whose {@link Owner#getIdentityKey() identity key} differs from this
544	     * owner's (so it is not already a hard duplicate) but whose lastName has the same
545	     * {@link Owner#soundex(String) soundex} and whose postcode matches; the earliest such owner (by
546	     * id) is returned. Two owners sharing a surname sound and postcode but differing in telephone (or
547	     * email) therefore surface here as a soft match rather than being rejected. A postcode is required
548	     * for a soft match, so an owner without a postcode never matches.
549	     */
550	    private Owner findSoftDuplicate(Owner owner) {
551	        if (owner.getPostcode() == null) {
552	            return null;
553	        }
554	        String candidateSoundex = Owner.soundex(owner.getLastName());
555	        String identityKey = owner.getIdentityKey();
556	        return activeOwners().stream()
557	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
558	            .filter(existing -> Owner.soundex(existing.getLastName()).equals(candidateSoundex))
559	            .filter(existing -> !identityKey.equals(existing.getIdentityKey()))
560	            .min(Comparator.comparingInt(Owner::getId))
561	            .orElse(null);
562	    }
563	
564	    /**
565	     * Build the memberId for a newly created owner, formatted {@code '<REGION><FY><HASH8><CHK>'}: the
566	     * region derived from the owner's postcode (or {@link Owner#UNKNOWN_REGION} when the postcode is
567	     * absent or maps to no known region), the 2-digit fiscal-year code FY of the business-day-adjusted
568	     * registrationDate, the first 8 upper-case hex characters HASH8 of the SHA-256 of the normalized
569	     * (E.164) telephone concatenated with the lastName, and a single Luhn check digit CHK over the
570	     * decimal digits of {@code <REGION><FY><HASH8>} (e.g. {@code 'NSW273C1A9F2B4'}). The
571	     * {@code <REGION><FY><HASH8><CHK>} value is computed by {@link Owner#computeMemberId()}; this is
572	     * the single source of the owner's identity, from which the owner's locality and fiscal year are
573	     * read back.
574	     *
575	     * <p>When the computed memberId collides with an existing owner's {@code memberId}, a
576	     * {@code '-<n>'} suffix is appended with the smallest {@code n} of 2 or more that makes the
577	     * memberId unique, and the de-duplicated memberId is returned.
578	     */
579	    private String memberId(Owner owner) {
580	        String base = owner.computeMemberId();
581	
582	        Set<String> existingIds = activeOwners().stream()
583	            .map(Owner::getMemberId)
584	            .filter(Objects::nonNull)
585	            .collect(Collectors.toSet());
586	
587	        if (!existingIds.contains(base)) {
588	            return base;
589	        }
590	        int n = 2;
591	        while (existingIds.contains(base + "-" + n)) {
592	            n++;
593	        }
594	        return base + "-" + n;
595	    }
