597	    /**
598	     * Whether the per-day owner creation limit has been reached for the given business day, i.e.
599	     * 100 or more owners already carry that {@code registrationDate}. The day is the adjusted
600	     * (business-day) registration date of the owner being created, so owners are counted per
601	     * business day. When true, a new owner must be rejected with {@code 429 Too Many Requests}.
602	     */
603	    private boolean isDailyLimitReached(LocalDate day) {
604	        long count = this.clinicService.findAllOwners().stream()
605	            .filter(existing -> day.equals(existing.getRegistrationDate()))
606	            .count();
607	        return count >= 100;
608	    }
