610	    /**
611	     * Whether creating this owner pushes the day's total past the bulk-signup threshold, i.e.
612	     * more than 80 owners have already been created for the given business day. Counts the owners
613	     * already carrying that {@code registrationDate} (the same accumulation as the daily-limit
614	     * rule); when that count exceeds 80 the newly created owner is flagged with a bulk-signup
615	     * warning.
616	     */
617	    private boolean isBulkSignup(LocalDate day) {
618	        long count = this.clinicService.findAllOwners().stream()
619	            .filter(existing -> day.equals(existing.getRegistrationDate()))
620	            .count();
621	        return count > 80;
622	    }
623	
624	    /**
625	     * Roll a registration date forward onto a business day: when it falls on a Saturday, Sunday or a
626	     * listed public holiday, advance it to the next non-holiday weekday; an ordinary weekday is
627	     * returned unchanged.
628	     */
629	    private LocalDate toBusinessDay(LocalDate date) {
630	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
631	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
632	            || PUBLIC_HOLIDAYS.contains(date)) {
633	            date = date.plusDays(1);
634	        }
635	        return date;
636	    }
