638	    /**
639	     * Whether the given city has reached its owner capacity, i.e. it already contains 50 or
640	     * more owners. Cities are compared case-insensitively.
641	     */
642	    private boolean isCityAtCapacity(String city) {
643	        return cityOwnerCount(city) >= 50;
644	    }
