646	    /**
647	     * Whether the given city is approaching its owner capacity, i.e. it already contains between 40
648	     * and 49 owners (inclusive) and so is nearing the {@link #isCityAtCapacity(String) hard capacity
649	     * limit} of 50. When true, a newly created owner in that city is flagged with a
650	     * {@code capacityWarning}; the hard rejection at 50 is unchanged. Cities are compared
651	     * case-insensitively.
652	     */
653	    private boolean isCityApproachingCapacity(String city) {
654	        long count = cityOwnerCount(city);
655	        return count >= 40 && count <= 49;
