658	    /**
659	     * The number of existing owners in the given city, compared case-insensitively. Counted over the
660	     * owners present before this create.
661	     */
662	    private long cityOwnerCount(String city) {
663	        return this.clinicService.findAllOwners().stream()
664	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
665	            .count();
