668	    /**
669	     * The number of existing owners that already share the given firstName and lastName,
670	     * compared case-insensitively (and with surrounding whitespace trimmed and internal
671	     * whitespace runs collapsed). Counted over the owners present before this create.
672	     */
673	    private int namesakeCount(String firstName, String lastName) {
674	        String candidateFirstName = normalizeName(firstName);
675	        String candidateLastName = normalizeName(lastName);
676	        return (int) activeOwners().stream()
677	            .filter(existing -> normalizeName(existing.getFirstName()).equals(candidateFirstName)
678	                && normalizeName(existing.getLastName()).equals(candidateLastName))
679	            .count();
