682	    /**
683	     * The number of members in this owner's household after this create: the count of existing
684	     * owners already carrying the same non-null {@code householdId} plus one for the owner being
685	     * created. An owner with no household ({@code householdId == null}) is a household of one.
686	     * Owners sharing a household are matched by their assigned {@code householdId}, so the count
687	     * does not depend on the order in which household members were created.
688	     */
689	    private int householdSize(String householdId) {
690	        if (householdId == null) {
691	            return 1;
692	        }
693	        long existing = this.clinicService.findAllOwners().stream()
694	            .filter(other -> householdId.equals(other.getHouseholdId()))
695	            .count();
696	        return (int) existing + 1;
697	    }
