699	    /**
700	     * Convert a raw telephone input to its E.164 representation, or {@code null} if it
701	     * cannot form a valid E.164 number.
702	     *
703	     * <p>A leading '+' and country code are kept when present; otherwise country code
704	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
705	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
706	     * carry 8 to 15 digits after the '+', and — for a recognised country calling code —
707	     * exactly the national-digit count that code requires (see
708	     * {@link Owner#hasValidNationalLength}); otherwise it is rejected as invalid.
709	     */
710	    private String toE164(String telephone) {
711	        if (telephone == null) {
712	            return null;
713	        }
714	        boolean hasCountryCode = telephone.trim().startsWith("+");
715	        String digits = telephone.replaceAll("\\D", "");
716	        String e164;
717	        if (hasCountryCode) {
718	            e164 = digits;
719	        } else {
720	            if (digits.startsWith("0")) {
721	                digits = digits.substring(1);
722	            }
723	            e164 = "61" + digits;
724	        }
725	        if (e164.length() < 8 || e164.length() > 15) {
726	            return null;
727	        }
728	        if (!Owner.hasValidNationalLength(e164)) {
729	            return null;
730	        }
731	        return "+" + e164;
732	    }
733	
734	    /**
735	     * The existing owners already registered in the household identified by {@code householdId}: the
736	     * {@linkplain #activeOwners() active owners} carrying that same non-null householdId. The owner
737	     * being created is not yet persisted, so it is never among them, and a {@code null} householdId
738	     * (an owner with no household) yields an empty collection. This is the single source of a
739	     * household's existing membership, shared by every rule keyed by an owner's household (the
740	     * {@link #membershipLevel(Owner) membership-level} derivation) so the set is never re-derived
741	     * elsewhere; like the other identity rules it ignores {@linkplain Owner#isDeleted() deleted}
742	     * owners.
743	     */
744	    private Collection<Owner> householdMembers(String householdId) {
745	        if (householdId == null) {
746	            return List.of();
747	        }
748	        return activeOwners().stream()
749	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
750	            .collect(Collectors.toList());
751	    }
752	
753	    /**
754	     * Normalize an owner's name for household comparison: trim, collapse internal whitespace runs
755	     * to a single space and lower-case. A null value normalizes to the empty string.
756	     */
757	    private String normalizeName(String value) {
758	        if (value == null) {
759	            return "";
760	        }
761	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
762	    }
763	
764	    /**
765	     * A stable shared identifier for the household an owner belongs to, derived deterministically
766	     * from its lastName and postcode. The lastName is normalized (case-insensitive,
767	     * whitespace-collapsed) before hashing, so every owner sharing the same lastName and postcode is
768	     * assigned the same value regardless of the order in which they are created. Formatted as the
769	     * first 12 upper-case hex characters of the SHA-256 of {@code '<normalizedLastName>|<postcode>'}
770	     * (an absent postcode contributes the empty string).
771	     */
772	    private String householdId(Owner owner) {
773	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
774	        String key = normalizeName(owner.getLastName()) + "|" + postcode;
775	        return shaHexUpper(key).substring(0, 12);
776	    }
777	
778	    /**
779	     * The upper-case rendering of the {@linkplain HashUtils#sha256Hex(String) SHA-256 hex} of
780	     * {@code input} (two hex characters per digest byte, so 64 characters in all). Callers that
781	     * need a shorter opaque token take a prefix of the result (e.g. {@link #householdId} keeps the
782	     * first 12 characters). The hashing itself lives in {@link HashUtils} so the one implementation is
783	     * shared with the owner's {@link Owner#getIdentityKey() identity key} and its
784	     * {@link Owner#computeMemberId() memberId} HASH8.
785	     */
786	    private String shaHexUpper(String input) {
787	        return HashUtils.sha256Hex(input).toUpperCase();
788	    }
789	
790	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
791	    @Override
792	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
793	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
794	        if (currentOwner == null) {
795	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
796	        }
797	        currentOwner.setAddress(ownerFieldsDto.getAddress());
798	        currentOwner.setCity(ownerFieldsDto.getCity());
799	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
800	        currentOwner.setLastName(ownerFieldsDto.getLastName());
801	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
802	        this.clinicService.saveOwner(currentOwner);
803	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
804	    }
805	
806	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
807	    @Transactional
808	    @Override
809	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
810	        Owner owner = this.clinicService.findOwnerById(ownerId);
811	        if (owner == null) {
812	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
813	        }
814	        this.clinicService.deleteOwner(owner);
815	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
816	    }
817	
818	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
819	    @Override
820	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
821	        Owner owner = this.clinicService.findOwnerById(ownerId);
822	        if (owner == null) {
823	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
824	        }
825	        HttpHeaders headers = new HttpHeaders();
826	        Pet pet = petMapper.toPet(petFieldsDto);
827	        owner.setId(ownerId);
828	        pet.setOwner(owner);
829	        pet.getType().setName(null);
830	        this.clinicService.savePet(pet);
831	        PetDto petDto = petMapper.toPetDto(pet);
832	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
833	            .buildAndExpand(pet.getId()).toUri());
834	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
835	    }
836	
837	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
838	    @Override
839	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
840	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
841	        if (currentOwner != null) {
842	            Pet currentPet = this.clinicService.findPetById(petId);
843	            if (currentPet != null) {
844	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
845	                currentPet.setName(petFieldsDto.getName());
846	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
847	                this.clinicService.savePet(currentPet);
848	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
849	            }
850	        }
851	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
852	    }
853	
854	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
855	    @Override
856	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
857	        HttpHeaders headers = new HttpHeaders();
858	        Visit visit = visitMapper.toVisit(visitFieldsDto);
859	        Pet pet = new Pet();
860	        pet.setId(petId);
861	        visit.setPet(pet);
862	        this.clinicService.saveVisit(visit);
863	        VisitDto visitDto = visitMapper.toVisitDto(visit);
864	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
865	            .buildAndExpand(visit.getId()).toUri());
866	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
867	    }
868	
869	
870	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
871	    @Override
872	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
873	        Owner owner = this.clinicService.findOwnerById(ownerId);
874	        if (owner != null) {
875	            Pet pet = owner.getPet(petId);
876	            if (pet != null) {
877	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
878	            }
879	        }
880	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
881	    }
882	}
